-- Cookbook: database schema and seed data
-- Import into an empty database in phpMyAdmin (Import tab).
-- categories -> recipes is one-to-many; every other table hangs off recipes
-- by recipe_id. Seed data: 6 categories and 40 recipes.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS images;
DROP TABLE IF EXISTS tips;
DROP TABLE IF EXISTS recipe_tools;
DROP TABLE IF EXISTS tools;
DROP TABLE IF EXISTS steps;
DROP TABLE IF EXISTS ingredients;
DROP TABLE IF EXISTS recipes;
DROP TABLE IF EXISTS categories;

SET FOREIGN_KEY_CHECKS = 1;

-- Each category stored once. Recipes point to it by category_id.
CREATE TABLE categories (
  category_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name        VARCHAR(50)  NOT NULL,
  PRIMARY KEY (category_id),
  UNIQUE KEY uq_categories_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per recipe. slug is the URL name and image folder name.
-- A recipe belongs to one category; a category has many recipes.
CREATE TABLE recipes (
  recipe_id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug              VARCHAR(100) NOT NULL,
  title             VARCHAR(150) NOT NULL,
  subtitle          VARCHAR(150) NOT NULL,
  category_id       INT UNSIGNED NOT NULL,
  servings          TINYINT UNSIGNED NOT NULL,
  description       TEXT NOT NULL,
  ingredient_count  TINYINT UNSIGNED NOT NULL,
  step_count        TINYINT UNSIGNED NOT NULL,
  main_image        VARCHAR(255) NOT NULL,
  ingredients_image VARCHAR(255) NOT NULL,
  image_folder      VARCHAR(255) NOT NULL,
  source_pdf        VARCHAR(255) NOT NULL,
  PRIMARY KEY (recipe_id),
  UNIQUE KEY uq_recipes_slug (slug),
  KEY idx_recipes_category (category_id),
  CONSTRAINT fk_recipes_category FOREIGN KEY (category_id)
    REFERENCES categories (category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per ingredient line. ORDER BY sort_order.
CREATE TABLE ingredients (
  ingredient_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  recipe_id     INT UNSIGNED NOT NULL,
  sort_order    TINYINT UNSIGNED NOT NULL,
  quantity      VARCHAR(20)  NOT NULL,
  unit          VARCHAR(20)  NULL,
  name          VARCHAR(255) NOT NULL,
  full_text     VARCHAR(255) NOT NULL,
  source        VARCHAR(20)  NOT NULL,
  PRIMARY KEY (ingredient_id),
  KEY idx_ingredients_recipe (recipe_id),
  CONSTRAINT fk_ingredients_recipe FOREIGN KEY (recipe_id)
    REFERENCES recipes (recipe_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per cooking step. ORDER BY step_number.
CREATE TABLE steps (
  step_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  recipe_id    INT UNSIGNED NOT NULL,
  step_number  TINYINT UNSIGNED NOT NULL,
  step_title   VARCHAR(150) NOT NULL,
  instructions TEXT NOT NULL,
  image        VARCHAR(255) NULL,
  image_retina VARCHAR(255) NULL,
  source       VARCHAR(20)  NOT NULL,
  PRIMARY KEY (step_id),
  KEY idx_steps_recipe (recipe_id),
  CONSTRAINT fk_steps_recipe FOREIGN KEY (recipe_id)
    REFERENCES recipes (recipe_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Each kitchen tool once.
CREATE TABLE tools (
  tool_id     INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name        VARCHAR(100) NOT NULL,
  brand       VARCHAR(100) NULL,
  description TEXT NOT NULL,
  image       VARCHAR(255) NOT NULL,
  image_2     VARCHAR(255) NULL,
  image_3     VARCHAR(255) NULL,
  PRIMARY KEY (tool_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Links each recipe to its tool.
CREATE TABLE recipe_tools (
  recipe_id INT UNSIGNED NOT NULL,
  tool_id   INT UNSIGNED NOT NULL,
  source    VARCHAR(20) NOT NULL,
  PRIMARY KEY (recipe_id, tool_id),
  KEY idx_recipe_tools_tool (tool_id),
  CONSTRAINT fk_recipe_tools_recipe FOREIGN KEY (recipe_id)
    REFERENCES recipes (recipe_id) ON DELETE CASCADE,
  CONSTRAINT fk_recipe_tools_tool FOREIGN KEY (tool_id)
    REFERENCES tools (tool_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- At most one tip per recipe. tip_type is how_to or ingredient_spotlight.
CREATE TABLE tips (
  tip_id    INT UNSIGNED NOT NULL AUTO_INCREMENT,
  recipe_id INT UNSIGNED NOT NULL,
  tip_title VARCHAR(150) NOT NULL,
  tip_text  TEXT NOT NULL,
  image     VARCHAR(255) NOT NULL,
  tip_type  VARCHAR(30)  NOT NULL,
  PRIMARY KEY (tip_id),
  UNIQUE KEY uq_tips_recipe (recipe_id),
  CONSTRAINT fk_tips_recipe FOREIGN KEY (recipe_id)
    REFERENCES recipes (recipe_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Every picture the site uses. recipe_id is empty for shared tool photos.
CREATE TABLE images (
  image_id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  recipe_id     INT UNSIGNED NULL,
  type          VARCHAR(30)  NOT NULL,
  step_number   TINYINT UNSIGNED NULL,
  label         VARCHAR(150) NOT NULL,
  size          VARCHAR(20)  NOT NULL,
  file_name     VARCHAR(150) NOT NULL,
  path          VARCHAR(255) NOT NULL,
  original_file VARCHAR(255) NOT NULL,
  PRIMARY KEY (image_id),
  KEY idx_images_recipe (recipe_id),
  CONSTRAINT fk_images_recipe FOREIGN KEY (recipe_id)
    REFERENCES recipes (recipe_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- categories: 6 rows

-- recipes: 40 rows

-- tools: 10 rows

-- ingredients: 428 rows

-- steps: 234 rows

-- recipe_tools: 40 rows

-- tips: 24 rows

-- images: 673 rows
